with FilteredOrderItems as (select * from order_items where quantity > 3), order_items_stats as (select order_id, case when quantity >= 9 then 'high' when quantity >= 2 then 'mid' else 'low' end as quantity_bucket, round(avg(quantity), 2) as avg_quantity from FilteredOrderItems group by order_id, case when quantity >= 9 then 'high' when quantity >= 2 then 'mid' else 'low' end) select order_id, quantity_bucket, avg_quantity from order_items_stats where avg_quantity < 32 order by quantity_bucket desc;
